// Fail-closed auth, same contract as every other VIO webhook. This endpoint spends no credits
// (Apollo's mixed_people/api_search is free), but it DOES reach a paid vendor with our key and
// returns real people's names to whoever calls it — an open endpoint here leaks a prospect list.
const expected = $env.VIO_WEBHOOK_TOKEN;
const item = $input.item.json;
const q = item.query || {};
const headers = item.headers || {};
const got = q.t || q.token || headers['x-vio-token'];
if (!expected) throw new Error('REFUSED: VIO_WEBHOOK_TOKEN not set (fail-closed)');
if (!got || String(got) !== String(expected)) throw new Error('REFUSED: bad or missing token');
return { json: item.body || item };

// Resolve the product to its ICP filters, and build the Apollo request body.
//
// FAILS CLOSED on an unknown product, exactly like VIO-sendr-generate-page: sourcing against a
// guessed ICP would put the wrong people into the pipeline, and every later stage would treat
// them as legitimate. Better to refuse than to source strangers.
//
// The ICP is embedded rather than read from config-<product>.json because n8n has no filesystem
// access to the repo. That makes this a THIRD copy of the ICP (config, this node, and the
// operator agents' validate_config). sync-routes.py does not yet cover `icp` — see its docstring.
const ICP = {
  oryoniq: {
    product: 'OryonIQ',
    person_titles: ['Capture Manager', 'VP of Business Development',
                    'Director of Business Development', 'Proposal Manager'],
    person_locations: ['United States'],
    q_keywords: 'government contracting',
  },
  visioneerit: {
    product: 'VisioneerIT',
    person_titles: ['CIO', 'CISO', 'Director of IT', 'IT Program Manager',
                    'Digital Transformation Lead'],
    person_locations: ['United States'],
    q_keywords: 'federal government IT modernization',
  },
};

const body = $input.first().json || {};
// Require a STRING. String(['oryoniq']) === 'oryoniq', so coercing here would let an array (or
// any object with a matching toString) through a gate whose whole job is to refuse the unknown.
// A gate that coerces is not a gate.
if (typeof body.product !== 'string') {
  throw new Error(`REFUSED: 'product' must be a string, got ${Array.isArray(body.product) ? 'array' : typeof body.product}`);
}
const key = body.product.trim().toLowerCase();
const icp = ICP[key];
if (!icp) {
  throw new Error(`REFUSED: unknown product '${body.product}'. Known: ${Object.keys(ICP).join(', ')}`);
}

// Hard cap. per_page is the only lever a caller has on result size, and an unbounded value would
// pull a huge page, blow the response size, and hand back a prospect list nobody asked for.
// 25 matches the operator agent's per-run budget ceiling.
const MAX = 25;
const asked = Number(body.limit);
const per_page = Number.isFinite(asked) && asked > 0 ? Math.min(Math.floor(asked), MAX) : 10;

return { json: {
  source_config: key,
  product: icp.product,
  per_page,
  capped: Number.isFinite(asked) && asked > MAX,
  apollo_body: {
    person_titles: icp.person_titles,
    person_locations: icp.person_locations,
    q_keywords: icp.q_keywords,
    page: 1,
    per_page,
  },
} };

// Filter Apollo's free results down to emailable leads and shape them onto the Sheet's column
// names. Mirrors engine.py: `[p for p in people if p.get('has_email')][:limit]`.
//
// NOTHING here spends a credit. has_email / has_direct_phone are FLAGS on the free search — the
// actual address requires people/match, which is a separate, human-gated step and is deliberately
// not reachable from this workflow.
const meta = $('Resolve ICP').first().json;
const resp = $input.first().json || {};
const people = Array.isArray(resp.people) ? resp.people : [];

const orgName = (p) => ((p.organization || {}).name)
  || ((p.account || {}).name) || p.organization_name || 'their firm';

// VERIFIED against the live API 2026-08-22: Apollo's FREE mixed_people/api_search does NOT
// return a company domain. `organization` carries `name` plus has_* booleans and nothing else —
// no primary_domain, no website_url. The extraction below is kept for paid/enriched shapes, but
// on the free path it correctly yields ''.
//
// This contradicts the comment on engine.py's org_domain(), which states the domain is "free — it
// comes back on Apollo's unpaid search". It does not. The consequence is real: company_domain
// drives Sendr's `gifSource: dynamic-website`, so without it the personalized page silently falls
// back to a generic preview instead of screenshotting the lead's own site.
const orgDomain = (p) => {
  const org = p.organization || p.account || {};
  const raw = org.primary_domain || org.website_url || '';
  if (!raw) return '';
  return String(raw).replace(/^https?:\/\//i, '').replace(/^www\./i, '').split('/')[0];
};

// Apollo returns has_direct_phone as a STRING on the free tier — literally
// "Maybe: please request direct dial via people/bulk_match". Boolean() on that is `true`, which
// would mark every lead as having a confirmed direct dial. It is a maybe, and it must say so.
const phoneState = (v) => {
  if (v === true) return true;
  if (typeof v === 'string' && /^maybe/i.test(v.trim())) return 'maybe';
  return Boolean(v);
};

const clean = (v, cap = 200) => (typeof v === 'string' ? v.replace(/[\u0000-\u001f\u007f]+/g, ' ').trim().slice(0, cap) : '');

const survivors = people.filter((p) => p && p.has_email).slice(0, meta.per_page);

const leads = survivors.map((p) => ({
  source_config: meta.source_config,
  apollo_id: clean(p.id, 64),
  first_name: clean(p.first_name, 80) || 'there',
  // Free search withholds the surname — only `last_name_obfuscated` (e.g. "B.") comes back.
  last_name: clean(p.last_name, 80),
  last_name_obfuscated: clean(p.last_name_obfuscated, 80),
  title: clean(p.title, 120) || '(role)',
  company: clean(orgName(p), 160),
  company_domain: clean(orgDomain(p), 160),
  has_email: Boolean(p.has_email),
  has_phone: phoneState(p.has_direct_phone),
  linkedin_url: clean(p.linkedin_url, 240),
  contact_email: '',        // stays empty — revealing costs a credit and is human-gated
}));

return [{ json: {
  source_config: meta.source_config,
  product: meta.product,
  returned_by_apollo: people.length,
  total_entries: resp.pagination ? resp.pagination.total_entries : (resp.total_entries ?? null),
  emailable: leads.length,
  dropped_no_email: people.length - survivors.length,
  per_page: meta.per_page,
  limit_capped: Boolean(meta.capped),
  credits_spent: 0,
  company_domain_available: leads.some((l) => l.company_domain !== ''),
  leads,
} }];

// Normalise for the caller and restate the boundary in the response itself — whoever reads this
// should not have to infer what did and did not happen. Strings are control-char scrubbed: n8n's
// lastNode response serialises with RAW control characters, which strict JSON parsers reject
// (found live 2026-08-16).
const scrub = (v) => Array.isArray(v) ? v.map(scrub)
  : (v && typeof v === 'object') ? Object.fromEntries(Object.entries(v).map(([k, x]) => [k, scrub(x)]))
  : (typeof v === 'string' ? v.replace(/[\u0000-\u001f\u007f]+/g, ' ') : v);

const r = $input.first().json;
return [{ json: scrub({
  ok: true,
  ran: ['resolve_icp', 'apollo_search_free', 'filter_has_email'],
  ...r,
  note: 'Apollo free search only. No lead credit was spent and no email address was revealed — '
      + 'revealing is people/match, a separate human-gated step this workflow cannot reach.',
}) }];
